/**
 * Jinx Cerenovus + Goblin: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Cerenovus
 * Wiki: https://wiki.bloodontheclocktower.com/Goblin
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { madAsPartners, ownJinxRules } from '#lib/core/rules/jinxes/jinxes.ts';
import { nightStepAlerts } from '#lib/core/rules/night/night-alerts.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Cerenovus + Goblin jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'cerenovus', 'goblin');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('cerenovus')?.name).toBe('Cerenovus');
		expect(data.byId.get('goblin')?.name).toBe('Goblin');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['cerenovus', 'goblin'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['cerenovus'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['goblin'])).not.toContain(jinx);
	});

	describe('the Cerenovus may make a player mad that they are the Goblin', () => {
		const ids = ['cerenovus', 'goblin', 'chef', 'empath', 'imp'];
		const base = scenario(['cerenovus', 'chef', 'empath', 'imp'], { script: scriptOf(ids) });

		it("is data in the Cerenovus's rules", () => {
			// Wiki: "The Cerenovus may choose to make a player mad that they are the Goblin."
			expect(ownJinxRules(base.game, 'cerenovus', 'goblin', base.characters)).toEqual({
				patch: {
					parts: {
						madAs: {
							token: 'Mad',
							mad: 'carrier',
							choose: ['townsfolk', 'outsider'],
							characters: ['goblin']
						}
					}
				}
			});
			expect(madAsPartners(base.game, 'cerenovus', base.characters)).toEqual(['goblin']);
		});

		it('says so at the Cerenovus step, the Goblin in play or not', () => {
			// Wiki: "The Cerenovus may choose to make a player mad that they are the Goblin."
			expect(
				nightStepAlerts(base.game, 'cerenovus', base.characters).filter(
					(a) => a.kind === 'may-mad-as'
				)
			).toMatchObject([{ seatId: base.seat('cerenovus'), partner: 'goblin' }]);
		});

		it('says nothing with the Goblin off the script', () => {
			// Wiki: "the Goblin"
			const ids = ['cerenovus', 'chef', 'empath', 'imp'];
			const s = scenario(ids, { script: scriptOf(ids) });
			expect(madAsPartners(s.game, 'cerenovus', s.characters)).toEqual([]);
		});
	});
});
